 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [r[:] for r in grid]
    # Recolor isolated 4-connected components of the grid's dominant background
    # when they are enclosed by non-background strokes.
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q = deque([(r,c)]); seen.add((r,c)); cells=[]; edge=False
            while q:
                y,x=q.popleft(); cells.append((y,x))
                if y in (0,h-1) or x in (0,w-1): edge=True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==bg:
                        seen.add((yy,xx)); q.append((yy,xx))
            if not edge:
                # Boundary color is the most frequent non-background neighbor.
                counts={}
                for y,x in cells:
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=bg:
                            v=grid[yy][xx]; counts[v]=counts.get(v,0)+1
                if counts:
                    color=max(counts,key=counts.get)
                    for y,x in cells: out[y][x]=color
    return out

